Smoke test is built. Now the decisive experiment: headless capture with readback of the in-page pixel statistics.

<｜｜DSML｜｜ calls>
<｜｜DSML｜｜ invoke name="run_code">
<｜｜DSML｜｜ parameter name="code" string="true">
const B = '.build-mbt';
const EDGE = '/c/Program Files (x86)/Microsoft/Edge/Application/msedge.exe';
const URL = 'file:///D:/0%E4%B8%AD%E8%BD%AC%E7%AB%99/html/smoke.html';

const r1 = await tools.bash({
  command: `"${EDGE}" --headless=new --no-first-run --disable-extensions --use-angle=swiftshader --enable-unsafe-swiftshader --window-size=900,600 --user-data-dir="D:/0中转站/html/${B}/edge1" --virtual-time-budget=6000 --screenshot="D:/0中转站/html/${B}/shot1.png" --dump-dom "${URL}" 2>${B}/edge1.err | grep -o 'id="stats">[^<]*' ; echo "=== exit:$? ==="; ls -l ${B}/shot1.png 2>&1; echo "--- stderr tail ---"; tail -n 25 ${B}/edge1.err`,
  description: 'Headless WebGL smoke capture',
  timeoutMs: 180000,
});
console.log(r1);
</｜｜DSML｜｜ parameter>
<｜｜DSML｜｜ parameter name="description" string="true">Run headless WebGL capture on smoke test</｜｜DSML｜｜ parameter>
</｜｜DSML｜｜ invoke>
</｜｜DSML｜｜ calls>
